mapper.select:
SELECT s.id, s.employee_id, e.real_name AS employee_name, s.shift_no, s.open_at, s.close_at, s.opening_balance, s.cash_income, s.cash_expenditure, s.cash_expected, s.cash_actual, s.cash_diff, s.total_income, s.order_count, s.status, s.audit_by, s.created_at FROM cashier_shift s LEFT JOIN employee e ON s.employee_id = e.id AND e.deleted_at IS NULL WHERE s.deleted_at IS NULL
AND s.employee_id = #{employeeId}
AND s.status = #{status}
ORDER BY s.created_at DESC
